"""Fail if paper/main.tex contains a result-like number that is not generated by make_numbers.py.

Checks, after removing comments, \\nv{...}, \\ci{...}, \\cite*/\\ref/\\label/\\url/\\input/\\includegraphics
arguments and LaTeX lengths:
  1. no decimal number (e.g. 2.63, 0.39) appears in the text -- results must come through \\nv;
  2. integers are reported for review with their context (counts such as 46 scenes or 1,210 images
     are allowed, but each is listed so a person can check it against its source);
  3. every \\nv key used exists in numbers.tsv (LaTeX would also stop on an unknown key).
Allowed literal decimals are the fixed settings listed in ALLOW, each with its source.
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEXS = [ROOT / "paper" / "main.tex", ROOT / "paper" / "appendix.tex"]
ALLOW = {  # literal -> where the setting is documented
    "0.5": "decision threshold used throughout (protocol, Section 4)",
    "6.5": "template text width (not in paper body)",
    "0.7": "FDRNet StepLR decay factor (upstream train.py --lr_gamma default; run config lr_gamma)",
    "2.15": "PyTorch version, recorded in every result file's config (torch: 2.15.0)",
    "0.05": "threshold label (sweep row)", "0.25": "threshold label (sweep row)", "0.50": "threshold label (sweep row)",
    "0.75": "threshold label (sweep row)", "0.95": "threshold label (sweep row)",
    "1.96": "normal quantile for a two-sided 95% interval (MDD definition, code/mdd_analysis.py)",
    "2.80": "1.96 + 0.84, normal quantiles for alpha 0.05 two-sided and 80% power (code/mdd_analysis.py)",
}


def strip(tex: str) -> str:
    tex = re.sub(r"(?<!\\)%.*", "", tex)
    tex = re.sub(r"\\(nv|ci)\{[^}]*\}", " ", tex)
    tex = re.sub(r"\\(cite[tp]?|ref|label|url|input|includegraphics|bibliography|bibliographystyle)(\[[^\]]*\])?\{[^}]*\}", " ", tex)
    tex = re.sub(r"\{@\{\}[^}]*\}", " ", tex)                      # tabular column specs
    tex = re.sub(r"[pL]\{\d+(\.\d+)?cm\}", " ", tex)
    tex = re.sub(r"\[width=[^\]]*\]", " ", tex)
    tex = re.sub(r"\\def\\(month|year)\{[^}]*\}", " ", tex)
    return tex


def main():
    raw = "\n".join(t.read_text() for t in TEXS)
    keys = {l.split("\t")[0] for l in (ROOT / "paper" / "numbers.tsv").read_text().splitlines()[1:]}
    live = "\n".join(l for l in re.sub(r"(?<!\\)%.*", "", raw).splitlines() if "\\newcommand" not in l)
    used = set(re.findall(r"\\nv\{([^}]*)\}", live)) | {k + s for k in re.findall(r"\\ci\{([^}]*)\}", live) for s in ("-lo", "-hi")}
    missing = sorted(used - keys)
    body = strip(raw)
    bad, ints = [], []
    for i, line in enumerate(body.splitlines(), 1):
        for m in re.finditer(r"(?<![\w.\\])(\d+\.\d+)(?![\w.])", line):
            if m.group(1) not in ALLOW:
                bad.append((i, m.group(1), line.strip()[:110]))
        for m in re.finditer(r"(?<![\w.\\{-])(\d[\d,]*)(?![\w.])", line):
            ints.append((i, m.group(1), line.strip()[:90]))
    print(f"\\nv keys used: {len(used)}; unknown keys: {missing or 'none'}")
    print(f"typed decimals outside \\nv: {len(bad)}")
    for b in bad:
        print("  line %d: %s  | %s" % b)
    print(f"typed integers to review: {len(ints)}")
    seen = set()
    for i, n, ctx in ints:
        if (n, ctx) not in seen:
            seen.add((n, ctx)); print(f"  {n:>6s}  | {ctx}")
    if missing or bad:
        sys.exit(1)


if __name__ == "__main__":
    main()
